/**
 * editor.ts — section-level edits on existing pages, for iterative
 * voice commands: "add a chart to the orders page", "remove the tabs".
 * Works on any page generated by build_page (relies on its
 * `{/* Section marker *\/}` comments); degrades gracefully otherwise.
 */
import {
  Section, SECTION_MARKERS, SectionCtx, defaultCtx,
  genSection, detectSections, UI_MODULES,
} from "./scaffold.js";

export interface EditOp {
  op: "add" | "remove";
  section: Section;
}

/** Parse ops from a spoken instruction. */
export function parseOps(instruction: string): EditOp[] {
  const low = instruction.toLowerCase();
  const sections = detectSections(low);
  if (sections.length === 0) return [];
  const removing = /\b(remove|delete|drop|get rid of|take (out|away)|without)\b/.test(low);
  const op: "add" | "remove" = removing ? "remove" : "add";
  return sections.map((section) => ({ op, section }));
}

function markerLine(section: Section): string {
  return `{/* ${SECTION_MARKERS[section]} */}`;
}

/** Net JSX tag-depth change for one line of well-formatted code. */
function depthDelta(line: string): number {
  const openings = (line.match(/<[A-Za-z][^\s/>]*/g) ?? []).length;
  const closings = (line.match(/<\/[A-Za-z]/g) ?? []).length;
  const selfClosing = (line.match(/\/>/g) ?? []).length;
  return openings - closings - selfClosing;
}

/**
 * A section = its marker comment + the single root JSX element after it.
 * We track tag depth from the root element until it closes — immune to
 * whatever follows (another section, the wrapper close, end of file).
 */
function findSectionRange(lines: string[], section: Section): [number, number] | null {
  const marker = markerLine(section);
  const start = lines.findIndex((l) => l.includes(marker));
  if (start === -1) return null;
  let depth = 0;
  let opened = false;
  let end = lines.length;
  for (let i = start + 1; i < lines.length; i++) {
    depth += depthDelta(lines[i]);
    if (depth > 0) opened = true;
    if (opened && depth <= 0) { end = i + 1; break; }
  }
  // consume trailing blank lines so removal leaves no gaps
  while (end < lines.length && lines[end].trim() === "") end++;
  return [start, end];
}

/** Top-level declarations each section depends on, with the identifier that proves usage. */
const HELPER_DECLS: Array<{ startRe: RegExp; usageRe: RegExp }> = [
  { startRe: /^function StatCard\(/, usageRe: /<StatCard\b/ },
  { startRe: /^const stats = \[/, usageRe: /\bstats\.map\(/ },
  { startRe: /^function ChartCard\(/, usageRe: /<ChartCard\b/ },
  { startRe: /^const items: Item\[\] = \[/, usageRe: /\bitems\.(map|length)\b/ },
  { startRe: /^interface Item \{/, usageRe: /\bItem\b(?!\s*\{)/ },
];

/** Remove declarations (and the cn import) that no longer have any usage. */
function pruneOrphans(code: string): string {
  let out = code;
  let changed = true;
  while (changed) {
    changed = false;
    for (const { startRe, usageRe } of HELPER_DECLS) {
      const lines = out.split("\n");
      const start = lines.findIndex((l) => startRe.test(l));
      if (start === -1) continue;
      // find end of declaration: first line that closes at column 0
      let end = start;
      for (let i = start + 1; i < lines.length; i++) {
        if (/^(\}|\];?)\s*$/.test(lines[i])) { end = i + 1; break; }
      }
      const rest = [...lines.slice(0, start), ...lines.slice(end)].join("\n");
      if (!usageRe.test(rest)) {
        out = rest.replace(/\n{3,}/g, "\n\n");
        changed = true;
      }
    }
  }
  if (!/\bcn\(/.test(out.replace(/^import .*$/gm, ""))) {
    out = out.replace(/^import \{ cn \} from "@\/lib\/utils";\n/m, "");
  }
  // prune unused named imports (components & icons)
  const body = out.replace(/^import .*$/gm, "");
  out = out
    .split("\n")
    .map((line) => {
      const m = /^import \{([^}]*)\} from ("(?:@\/components\/ui\/[^"]+|lucide-react)");$/.exec(line);
      if (!m) return line;
      const used = m[1].split(",").map((s) => s.trim()).filter(Boolean)
        .filter((name) => new RegExp(`[<{(\\s.,]${name}\\b`).test(body));
      return used.length ? `import { ${used.join(", ")} } from ${m[2]};` : null;
    })
    .filter((l): l is string => l !== null)
    .join("\n");
  return out;
}

/** Merge needed UI/icon imports into existing import lines. */
function mergeImports(code: string, ui: string[], icons: string[], needCn: boolean): string {
  let out = code;
  // group ui names by module
  const byModule = new Map<string, string[]>();
  for (const [mod, names] of Object.entries(UI_MODULES)) {
    const used = names.filter((n) => ui.includes(n));
    if (used.length) byModule.set(mod, used);
  }
  const lastImportIdx = () => {
    const ls = out.split("\n");
    let idx = -1;
    ls.forEach((l, i) => { if (/^import\b/.test(l)) idx = i; });
    return { ls, idx };
  };
  for (const [mod, names] of byModule) {
    const re = new RegExp(`import \\{([^}]*)\\} from "@/components/ui/${mod}";`);
    const m = re.exec(out);
    if (m) {
      const existing = m[1].split(",").map((s) => s.trim()).filter(Boolean);
      const merged = [...new Set([...existing, ...names])];
      out = out.replace(re, `import { ${merged.join(", ")} } from "@/components/ui/${mod}";`);
    } else {
      const { ls, idx } = lastImportIdx();
      ls.splice(idx + 1, 0, `import { ${names.join(", ")} } from "@/components/ui/${mod}";`);
      out = ls.join("\n");
    }
  }
  if (icons.length) {
    const re = /import \{([^}]*)\} from "lucide-react";/;
    const m = re.exec(out);
    if (m) {
      const existing = m[1].split(",").map((s) => s.trim()).filter(Boolean);
      const merged = [...new Set([...existing, ...icons])].sort();
      out = out.replace(re, `import { ${merged.join(", ")} } from "lucide-react";`);
    } else {
      const { ls, idx } = lastImportIdx();
      ls.splice(idx + 1, 0, `import { ${icons.sort().join(", ")} } from "lucide-react";`);
      out = ls.join("\n");
    }
  }
  if (needCn && !out.includes(`from "@/lib/utils"`)) {
    const { ls, idx } = lastImportIdx();
    ls.splice(idx + 1, 0, `import { cn } from "@/lib/utils";`);
    out = ls.join("\n");
  }
  return out;
}

/** Insert top-level helper declarations after the imports if missing. */
function mergeHelpers(code: string, helpers: string[]): string {
  let out = code;
  for (const h of helpers) {
    const signature = h.split("\n")[0].slice(0, 40);
    if (out.includes(signature)) continue; // already present
    const ls = out.split("\n");
    let idx = -1;
    ls.forEach((l, i) => { if (/^import\b/.test(l)) idx = i; });
    ls.splice(idx + 1, 0, "", h);
    out = ls.join("\n");
  }
  return out;
}

export function applyOps(
  code: string,
  ops: EditOp[],
  ctx?: Partial<SectionCtx> & { title?: string; columns?: string[]; stats?: string[]; charts?: string[] }
): { code: string; applied: string[]; warnings: string[] } {
  let out = code;
  const applied: string[] = [];
  const warnings: string[] = [];

  // infer page title from the existing h1 for section content
  const titleMatch = /<h1[^>]*>([^<{]+)<\/h1>/.exec(code);
  const title = ctx?.title ?? titleMatch?.[1]?.trim() ?? "Items";
  const sectionCtx = defaultCtx(title, ctx ?? {});

  for (const { op, section } of ops) {
    const lines = out.split("\n");
    const range = findSectionRange(lines, section);

    if (op === "remove") {
      if (!range) {
        warnings.push(`Cannot remove '${section}': no '${markerLine(section)}' marker found in the file.`);
        continue;
      }
      lines.splice(range[0], range[1] - range[0]);
      // collapse double blank lines left behind, drop now-unused helpers
      out = pruneOrphans(lines.join("\n").replace(/\n{3,}/g, "\n\n"));
      applied.push(`removed ${section}`);
      continue;
    }

    // add
    if (range) {
      warnings.push(`Skipped adding '${section}': section already exists (line ${range[0] + 1}).`);
      continue;
    }
    const block = genSection(section, sectionCtx);
    // insert before the wrapper close: last occurrence of the inner `      </div>`
    let insertAt = -1;
    for (let i = lines.length - 1; i >= 0; i--) {
      if (/^      <\/div>\s*$/.test(lines[i])) { insertAt = i; break; }
    }
    if (insertAt === -1) {
      warnings.push(`Cannot add '${section}': page wrapper not recognized. Use build_page to regenerate.`);
      continue;
    }
    lines.splice(insertAt, 0, "", ...block.jsx.split("\n"));
    out = lines.join("\n");
    out = mergeImports(out, block.ui, block.icons, block.needCn);
    out = mergeHelpers(out, block.helpers);
    applied.push(`added ${section}`);
  }

  return { code: out, applied, warnings };
}
